# MAGIC %md
# MAGIC # SimpleAWGold — ProcessTable
# MAGIC
# MAGIC Parameterized ETL notebook — processes any table in this model.
# MAGIC Receives table configuration as a JSON widget argument from RunAllNotebooks.
# MAGIC Generated by CoreAccelerate.

# COMMAND ----------

import json

dbutils.widgets.text("table_name",   "",   "Table Name")
dbutils.widgets.text("model_name",   "",   "Model Name")
dbutils.widgets.text("table_config", "{}", "Table Configuration JSON")

table_name = dbutils.widgets.get("table_name")
model_name = dbutils.widgets.get("model_name")
_cfg       = json.loads(dbutils.widgets.get("table_config"))

# COMMAND ----------

# Display model and table context
displayHTML(
    f'<div style="font-family:sans-serif;padding:8px 12px;'
    f'background:#f0f4ff;border-left:4px solid #4a6cf7;border-radius:4px;'
    f'margin-bottom:4px">'
    f'<span style="font-size:0.8em;color:#555;text-transform:uppercase;'
    f'letter-spacing:.05em">Model</span><br>'
    f'<strong style="font-size:1.1em">{model_name}</strong>'
    f'&nbsp;&nbsp;<span style="color:#888">›</span>&nbsp;&nbsp;'
    f'<span style="font-size:0.8em;color:#555;text-transform:uppercase;'
    f'letter-spacing:.05em">Table</span><br>'
    f'<strong style="font-size:1.1em">{table_name}</strong>'
    f'</div>'
)

# COMMAND ----------

from pyspark.sql import SparkSession
from pyspark.sql import functions as F
from pyspark.sql.functions import (
    col, sha2, concat, lit, coalesce, expr, hex,
    current_timestamp, current_date, to_date, when, isnull,
)
from pyspark.sql.types import BinaryType, LongType
from delta.tables import DeltaTable

catalog  = _cfg["catalog"]
database = _cfg["database"]

if _cfg.get("ansi_mode"):
    spark.sql("SET spark.sql.ansi.enabled = true")

import time as _time
_tbl_run_start = _time.time()

# COMMAND ----------

# Debug — drop destination table data before processing
if _cfg.get("delete_table_data_in_debug"):
    _drop_tbl = f"{catalog}.{database}.{table_name}"
    print(f"[DEBUG] Dropping table: {_drop_tbl}")
    spark.sql(f"DROP TABLE IF EXISTS {_drop_tbl}")

# COMMAND ----------

# Pre-run notebook (runs before table processing)
if _cfg.get("pre_run_notebook_path"):
    dbutils.notebook.run(_cfg["pre_run_notebook_path"], timeout_seconds=0)

# COMMAND ----------

# Custom beginning cell (per-table, from config)
# NOTE: content originates from trusted-internal table configuration.
_beginning_cell = _cfg.get("beginning_cell")
if _beginning_cell:
    exec(compile(_beginning_cell, "<beginning_cell>", "exec"), globals())

# COMMAND ----------

# Source path and file pattern (file-based)
if _cfg["source_type"] == "file":
    source_path  = _env_subst(_cfg["source_path"]) if "_env_subst" in dir() else _cfg["source_path"]
    file_pattern = _cfg["file_pattern"]

    if _cfg.get("use_iso_dated_folders"):
        import re as _re
        _iso_re = _re.compile(_cfg.get("iso_date_folder_regex") or r'^\d{14}$')
        _subfolders = [
            f.name.rstrip('/') for f in dbutils.fs.ls(source_path)
            if _iso_re.match(f.name.rstrip('/'))
        ]
        _subfolders.sort(reverse=True)
        if _subfolders:
            source_path = source_path + '/' + _subfolders[0]

# COMMAND ----------

# Source read
if _cfg["source_type"] == "file" and not _cfg.get("hwm_file_path_mode", False):
    if _cfg.get("source_most_recent_file_only"):
        _files = sorted(
            dbutils.fs.ls(source_path),
            key=lambda f: f.modificationTime,
            reverse=True,
        )
        _load_path = _files[0].path
    else:
        _load_path = source_path

    if _cfg.get("use_auto_loader"):
        _schema_loc = f"/Volumes/{catalog}/{database}/schema_inference/{table_name}"
        source_df = (
            spark.readStream
            .format("cloudFiles")
            .option("cloudFiles.format", _cfg["file_type"])
            .option("cloudFiles.schemaLocation", _schema_loc)
            .option("cloudFiles.inferColumnTypes", "true")
            .load(f"{_load_path}/{file_pattern}")
        )
    else:
        _reader = spark.read.format(_cfg["file_type"])
        for _k, _v in _cfg.get("read_options", {}).items():
            _reader = _reader.option(_k, _v)
        source_df = _reader.load(f"{_load_path}/{file_pattern}")

    _sel_exprs = _cfg.get("select_expressions", [])
    if _sel_exprs:
        source_df.createOrReplaceTempView("raw_source")
        source_df = spark.sql("SELECT\n" + ",\n".join(_sel_exprs) + "\nFROM raw_source")
elif _cfg["source_type"] != "file":
    _src_cat   = _cfg.get("source_catalog") or catalog
    _src_db    = _cfg.get("source_database") or database
    _tbl_query = _cfg.get("table_query")
    if _tbl_query:
        source_df = spark.sql(_tbl_query)
    else:
        source_df = spark.read.table(f"{_src_cat}.{_src_db}.{table_name}")

# COMMAND ----------

# Custom pre-query cell (per-table, from config)
# NOTE: content originates from trusted-internal table configuration.
_pre_query_cell = _cfg.get("pre_query_cell")
if _pre_query_cell:
    exec(compile(_pre_query_cell, "<pre_query_cell>", "exec"), globals())

# COMMAND ----------

# Apply pre-computed column transforms
# (skipped in hwm_file_path_mode — applied after HWM source read in Cell 8)
if not _cfg.get("hwm_file_path_mode", False):
    # Source column renames run first so every expression/SK/FK/ChangeHash
    # entry below — and the unconditional audit-datetime injection — sees
    # columns already under their declared name.
    for _src_col, _dst_col in _cfg.get("column_renames", []):
        source_df = source_df.withColumnRenamed(_src_col, _dst_col)
    for _col_name, _col_expr in _cfg.get("column_expressions", []):
        source_df = source_df.withColumn(_col_name, expr(_col_expr))
    # Scratch columns (shared hash pre-image) must never reach the target table.
    if _cfg.get("column_drops"):
        source_df = source_df.drop(*_cfg["column_drops"])

# COMMAND ----------

# High-watermark incremental filter
if _cfg.get("use_high_watermark"):
    _hwm_table = f"{catalog}.{database}.HighWatermark"
    if _cfg.get("hwm_file_path_mode"):
        # File-path HWM mode
        _hwm_root = _env_subst(_cfg.get("hwm_source_root", "")) if "_env_subst" in dir() else _cfg.get("hwm_source_root", "")
        _sentinel = "__file_path__"
        try:
            _hwm_df  = spark.sql(
                f"SELECT MaxValue FROM {_hwm_table}"
                f" WHERE TableName = '{table_name}' AND ColumnName = '{_sentinel}'"
            )
            _hwm_val = _hwm_df.collect()[0][0] if _hwm_df.count() > 0 else None
        except Exception:
            _hwm_val = None

        # folder_traversal_depth: 1 = current folder only (no recursion);
        # N>1 = descend N-1 sublevels; <=0 = unlimited (escape hatch).
        _max_depth = int(_cfg.get("folder_traversal_depth", 1) or 0)
        def _ls_recursive(path, _depth=1):
            results = []
            for f in dbutils.fs.ls(path):
                if f.isDir():
                    if _max_depth <= 0 or _depth < _max_depth:
                        results.extend(_ls_recursive(f.path, _depth + 1))
                else:
                    results.append(f.path)
            return results

        def _rel(p):
            if _hwm_root and p.startswith(_hwm_root + "/"):
                return p[len(_hwm_root) + 1:]
            return p

        _all_files = _ls_recursive(source_path)
        if file_pattern:
            import fnmatch as _fnm
            _all_files = [p for p in _all_files if _fnm.fnmatch(p.split("/")[-1], file_pattern)]
        _ls_all    = list(_all_files)
        if _hwm_val:
            _all_files = [p for p in _all_files if _rel(p) > _hwm_val]

        if _all_files:
            source_df = spark.read.format(_cfg["file_type"]).load(_all_files)
        elif _ls_all:
            source_df = spark.createDataFrame([], spark.read.format(_cfg["file_type"]).load(_ls_all[:1]).limit(0).schema)
        else:
            print("No files found at source path — skipping run.")
            dbutils.notebook.exit("no_files")

        _sel_exprs = _cfg.get("select_expressions", [])
        if _sel_exprs:
            source_df.createOrReplaceTempView("_hwm_raw_source")
            source_df = spark.sql("SELECT\n" + ",\n".join(_sel_exprs) + "\nFROM _hwm_raw_source")

        # Renames + column expressions now (deferred from Cell 7 in hwm_file_path_mode)
        for _src_col, _dst_col in _cfg.get("column_renames", []):
            source_df = source_df.withColumnRenamed(_src_col, _dst_col)
        for _col_name, _col_expr in _cfg.get("column_expressions", []):
            source_df = source_df.withColumn(_col_name, expr(_col_expr))
        if _cfg.get("column_drops"):
            source_df = source_df.drop(*_cfg["column_drops"])

        _max_file_path = max(_rel(p) for p in _all_files) if _all_files else None
        # HWM commit deferred — see HWM Commit cell (runs after target MERGE)
    else:
        # Column-based HWM mode
        # FIX-4: fail fast when column-mode HWM is selected without an explicit
        # hwm_column_name — never silently fall back to an assumed column name.
        _hwm_col   = _cfg.get("hwm_column_name")
        if not _hwm_col:
            raise ValueError(
                "Column-mode high-watermark requires a non-empty hwm_column_name "
                "(use_high_watermark=true with high_watermark_file_level=false). "
                f"Table {table_name!r} has no hwm_column_name configured."
            )
        try:
            _hwm_df  = spark.sql(
                f"SELECT MaxValue FROM {_hwm_table}"
                f" WHERE TableName = '{table_name}' AND ColumnName = '{_hwm_col}'"
            )
            _hwm_val = _hwm_df.collect()[0][0] if _hwm_df.count() > 0 else None
        except Exception:
            _hwm_val = None

        if _hwm_val is not None:
            source_df = source_df.filter(col(_hwm_col) > lit(_hwm_val))

        _max_hwm = source_df.agg({_hwm_col: "max"}).collect()[0][0]
        # HWM commit deferred — see HWM Commit cell (runs after target MERGE)

# COMMAND ----------

# Create target Delta table if it does not exist
if _cfg.get("include_create_statements") and _cfg.get("create_table_ddl"):
    spark.sql(_cfg["create_table_ddl"])
    # SCD Type 4 history tables — one per tracked column
    for _t4 in _cfg.get("type4_columns", []):
        _hist_tbl = f"{catalog}.{database}.{table_name}_{_t4['name']}_History"
        spark.sql(f"""
            CREATE TABLE IF NOT EXISTS {_hist_tbl} (
              {_t4['sk_name']} BINARY,
              {_t4['name']} {_t4['type']},
              Audit_EffectiveDate TIMESTAMP,
              Audit_ExpiredDate TIMESTAMP
            ) USING delta
        """)

# COMMAND ----------

# Data quality expectations — evaluation
if _cfg.get("expectations_enabled") and _cfg.get("expectations"):
    _exps  = _cfg["expectations"]
    _esafe = lambda n: "".join(c if (c.isalnum() or c == "_") else "_" for c in n)
    source_df = source_df
    for _exp in _exps:
        source_df = source_df.withColumn(
            f"_exp_{_esafe(_exp['name'])}",
            expr(_exp["expression"]),
        )

# COMMAND ----------

# Data quality expectations — action routing
if _cfg.get("expectations_enabled") and _cfg.get("expectations"):
    _exps  = _cfg["expectations"]
    _esafe = lambda n: "".join(c if (c.isalnum() or c == "_") else "_" for c in n)

    # Drop rows failing 'drop' expectations
    for _exp in _exps:
        if _exp.get("action") == "drop":
            source_df = source_df.filter(expr(f"_exp_{_esafe(_exp['name'])}"))

    # Fail immediately on 'fail' expectation violations
    for _exp in _exps:
        if _exp.get("action") == "fail":
            _fail_cnt = source_df.filter(~expr(f"_exp_{_esafe(_exp['name'])}")).count()
            if _fail_cnt > 0:
                raise RuntimeError(
                    f"Expectation '{_exp['name']}' failed: {_fail_cnt} violating rows"
                )

    # Separate audit rows for audit_only and write_and_audit expectations
    _has_audit = any(_exp.get("action") in ("audit_only", "write_and_audit") for _exp in _exps)
    if _has_audit:
        _audit_rows_df = source_df.filter(
            " OR ".join(
                f"NOT _exp_{_esafe(e['name'])}"
                for e in _exps
                if e.get("action") in ("audit_only", "write_and_audit")
            )
        )
        # For audit_only: exclude violating rows from main load
        _audit_only_exps = [e for e in _exps if e.get("action") == "audit_only"]
        for _exp in _audit_only_exps:
            source_df = source_df.filter(expr(f"_exp_{_esafe(_exp['name'])}"))

# COMMAND ----------

# Source deduplication — prevents DELTA_MULTIPLE_SOURCE_ROW_MATCHING_TARGET_ROW_IN_MERGE
if _cfg.get("dedup_source_enabled") and not _cfg.get("truncate_and_load"):
    from pyspark.sql.window import Window
    from pyspark.sql.functions import row_number
    _dedup_keys  = _cfg["merge_key_columns"]
    if not _dedup_keys:
        raise RuntimeError(
            "merge_key_columns is empty — cannot deduplicate without a key. "
            "Set at least one merge key column in the table configuration."
        )
    _recency_col = _cfg.get("dedup_source_recency_column") or ""
    if _recency_col:
        _dedup_win = (
            Window
            .partitionBy(*_dedup_keys)
            .orderBy(col(_recency_col).desc_nulls_last())
        )
        source_df = (
            source_df
            .withColumn("_dedup_rn", row_number().over(_dedup_win))
            .filter(col("_dedup_rn") == 1)
            .drop("_dedup_rn")
        )
    else:
        # No recency column configured: non-deterministic deduplication.
        # One row per merge-key group is kept but which row is unspecified.
        source_df = source_df.dropDuplicates(_dedup_keys)

# COMMAND ----------

# Capture pre-operation row count for accurate RowsBefore audit metric
# (correct for MERGE, truncate-and-load and append — independent of Delta op type)
if _cfg.get("table_statistics_enabled"):
    try:
        _rows_before = spark.sql(f"SELECT COUNT(*) AS cnt FROM {catalog}.{database}.{table_name}").collect()[0]["cnt"]
    except Exception:
        _rows_before = 0

# COMMAND ----------

# Cache the final pre-merge source once; it is re-read by several cells until it is released.
_source_cached = not source_df.isStreaming and not _cfg.get("truncate_and_load")

def _release_source_cache():
    global _source_cached
    if _source_cached:
        _source_cached = False
        try:
            source_df.unpersist()
        except Exception:
            pass

if _source_cached:
    try:
        _persisted_df = source_df.persist()
    except Exception as _cache_err:
        # Serverless compute rejects DataFrame caching: run uncached (source_df is untouched).
        _source_cached = False
        print(f"Source cache skipped ({type(_cache_err).__name__}); running uncached.")
    else:
        source_df = _persisted_df
        try:
            source_df.count()  # materialize once
        except BaseException:
            # A real source read error: release the cache and surface it (never masked as a fallback)
            _release_source_cache()
            raise

try:
    # MERGE into target Delta table
    _merge_keys  = _cfg["merge_key_columns"]
    _target_cols = _cfg["target_columns"]
    _on_pred     = " AND ".join(f"target.{k} = source.{k}" for k in _merge_keys)
    _update_cols = [c for c in _target_cols if c != "Audit_CreatedDateTime"]
    _update_set  = ",\n    ".join(f"target.{c} = source.{c}" for c in _update_cols)
    _insert_cols = ",\n    ".join(_target_cols)
    _insert_vals = ",\n    ".join(f"source.{c}" for c in _target_cols)
    _not_in_src  = ""
    if _cfg.get("not_in_source_deletes_enabled"):
        if _cfg.get("hard_deletes", True):
            _not_in_src = "\nWHEN NOT MATCHED BY SOURCE THEN\n  DELETE"
        else:
            # Non-SCD2 soft delete (the SCD2 NISD is its own statement below): flag the row.
            # NULL flag (row from before the column existed) counts as not deleted; flagged
            # rows are not re-touched.
            _not_in_src = (
                "\nWHEN NOT MATCHED BY SOURCE AND coalesce(target.Audit_IsDeleted, false) = false THEN\n"
                "  UPDATE SET target.Audit_IsDeleted = true,\n"
                "             target.Audit_ModifiedDateTime = current_timestamp()"
            )

    if _cfg.get("not_in_source_deletes_enabled") and not _cfg.get("truncate_and_load") and source_df.count() == 0:
        raise RuntimeError(
            "MERGE aborted: source DataFrame is empty and not_in_source_deletes_enabled=True. "
            f"Running this MERGE would delete all rows from {table_name}. "
            "Disable not_in_source_deletes_enabled or fix the source."
        )

    # Serverless-safe schema evolution: add any missing columns before MERGE
    try:
        _tgt_fields = {f.name for f in spark.table(f"{catalog}.{database}.{table_name}").schema.fields}
        _new_cols = [f for f in source_df.schema.fields if f.name not in _tgt_fields and not f.name.startswith('_exp_')]
        if _new_cols:
            _add_ddl = ", ".join(f"`{f.name}` {f.dataType.simpleString()}" for f in _new_cols)
            spark.sql(f"ALTER TABLE {catalog}.{database}.{table_name} ADD COLUMNS ({_add_ddl})")
    except Exception:
        pass  # Table may not exist yet on first run — CREATE TABLE cell handles creation

    # SCD Type 4 history capture — record previous column values before main MERGE
    if _cfg.get("type4_columns"):
        source_df.createOrReplaceTempView("_source_data")
        for _t4 in _cfg["type4_columns"]:
            _t4_name = _t4['name']
            _t4_sk   = _t4['sk_name']
            _hist_uc = f"{catalog}.{database}.{table_name}_{_t4_name}_History"
            spark.sql(f"""
            MERGE INTO {_hist_uc} AS hist
            USING (
              SELECT t.{_t4_sk}, t.{_t4_name},
                     t.Audit_CreatedDateTime AS Audit_EffectiveDate,
                     current_timestamp() AS Audit_ExpiredDate
              FROM {catalog}.{database}.{table_name} t
              INNER JOIN _source_data s ON t.{_t4_sk} = s.{_t4_sk}
              WHERE NOT (t.{_t4_name} <=> s.{_t4_name})
            ) AS src
            ON hist.{_t4_sk} = src.{_t4_sk}
            AND hist.Audit_EffectiveDate = src.Audit_EffectiveDate
            WHEN NOT MATCHED THEN INSERT *
        """)

    if _cfg.get("truncate_and_load"):
        # Truncate-and-load: full table replace — atomically clear then append all source rows
        spark.sql(f"TRUNCATE TABLE {catalog}.{database}.{table_name}")
        source_df.write.mode("append").format("delta").saveAsTable(f"{catalog}.{database}.{table_name}")
    elif _cfg.get("effective_dates_enabled"):
        # SCD2: initialise legacy rows (NULL Audit_RowIsCurrent) so the SCD2 merge and the stale-folder
        # guard see them as current history. Probe first: steady-state runs rewrite nothing. Only keys
        # with no current row are initialised (one current row per key). Dates keep real values (COALESCE).
        _ik = _cfg["merge_key_columns"]
        if spark.sql(f"SELECT 1 FROM {catalog}.{database}.{table_name} WHERE Audit_RowIsCurrent IS NULL LIMIT 1").collect():
            _i_set = (
                "target.Audit_RowIsCurrent = true, "
                "target.Audit_EffectiveDate = COALESCE(target.Audit_EffectiveDate, CAST('1900-01-01' AS TIMESTAMP)), "
                "target.Audit_ExpiredDate = COALESCE(target.Audit_ExpiredDate, CAST('9999-12-31' AS TIMESTAMP))"
            )
            if _ik:
                _i_sel = ", ".join(_ik)
                _i_on  = " AND ".join(f"target.{k} = cur.{k}" for k in _ik)
                spark.sql(f"""
                MERGE INTO {catalog}.{database}.{table_name} AS target
                USING (SELECT DISTINCT {_i_sel} FROM {catalog}.{database}.{table_name}
                       WHERE Audit_RowIsCurrent = true) AS cur
                ON {_i_on}
                WHEN NOT MATCHED BY SOURCE AND target.Audit_RowIsCurrent IS NULL THEN UPDATE SET
                  {_i_set}
            """)
            else:
                spark.sql(f"""
                UPDATE {catalog}.{database}.{table_name} AS target SET {_i_set}
                WHERE target.Audit_RowIsCurrent IS NULL
            """)
        # Changed = not null-safe-equal; "unchanged" (below) is its exact complement
        _change_cond = "AND NOT (t.ChangeHash <=> s.ChangeHash) " if _cfg.get("change_hash_enabled") else ""
        _on_pred_ts  = " AND ".join(f"t.{k} = s.{k}" for k in _merge_keys)
        source_df.createOrReplaceTempView("_new_rows")
        # A NULL target ChangeHash is 'changed' (null-safe): expired and re-versioned once.
        if _cfg.get("key_only"):
            # Key-only table: no business columns, so no key can change: nothing to expire.
            _expired = spark.sql(f"SELECT t.* FROM {catalog}.{database}.{table_name} t WHERE false")
        else:
            _expired = spark.sql(f"""
            SELECT t.*
            FROM {catalog}.{database}.{table_name} t
            INNER JOIN _new_rows s
              ON {_on_pred_ts}
              {_change_cond}AND t.Audit_RowIsCurrent = true
              AND t.Audit_EffectiveDate < s.Audit_EffectiveDate
        """)
        _eff_date = (
            source_df.select("Audit_EffectiveDate").limit(1).collect()[0][0]
            if source_df.count() > 0 else None
        )
        _eff_date_col = lit(_eff_date) if _eff_date is not None else current_timestamp()
        _expired = (
            _expired
            .withColumn("Audit_ExpiredDate", _eff_date_col)
            .withColumn("Audit_RowIsCurrent", lit(False))
        )
        # Unchanged keys (current row has the same ChangeHash) are NOT re-inserted as new
        # versions; they stay visible to the NISD step below via the full _new_rows view.
        if _cfg.get("change_hash_enabled"):
            _scd_rows = spark.sql(f"""
            SELECT s.*
            FROM _new_rows s
            WHERE NOT EXISTS (
                SELECT 1 FROM {catalog}.{database}.{table_name} t
                WHERE {_on_pred_ts}
                  AND t.Audit_RowIsCurrent = true
                  AND t.ChangeHash <=> s.ChangeHash
            )
        """)
        elif _cfg.get("key_only"):
            # Key-only: only keys with no current row are new versions (reappearing keys included)
            _scd_rows = spark.sql(f"""
            SELECT s.*
            FROM _new_rows s
            WHERE NOT EXISTS (
                SELECT 1 FROM {catalog}.{database}.{table_name} t
                WHERE {_on_pred_ts}
                  AND t.Audit_RowIsCurrent = true
            )
        """)
        else:
            _scd_rows = source_df  # no ChangeHash: every matched key is a new version
        _merge_src = _scd_rows.unionByName(_expired)
        _merge_src.createOrReplaceTempView("_merge_source")
        _src_alias = "_merge_source"
        _on_scd2   = _on_pred + " AND target.Audit_EffectiveDate = source.Audit_EffectiveDate"
        spark.sql(f"""
        MERGE INTO {catalog}.{database}.{table_name} AS target
        USING {_src_alias} AS source
        ON {_on_scd2}
        WHEN MATCHED THEN UPDATE SET
          {_update_set}
        WHEN NOT MATCHED THEN INSERT (
          {_insert_cols}
        ) VALUES (
          {_insert_vals}
        )
    """)
        if _cfg.get("not_in_source_deletes_enabled"):
            # SCD2 NISD: only CURRENT rows whose key is absent from the FULL source snapshot;
            # expired history and keys present in the source (changed or unchanged) are untouched.
            if _cfg.get("hard_deletes", True):
                _nis_action = "DELETE"
            else:
                from pyspark.sql.functions import date_format
                _eff_date_str = spark.range(1).select(
                    date_format(_eff_date_col, "yyyy-MM-dd HH:mm:ss.SSSSSS")
                ).collect()[0][0]
                _nis_action = (
                    "UPDATE SET target.Audit_RowIsCurrent = false, "
                    f"target.Audit_ExpiredDate = CAST('{_eff_date_str}' AS TIMESTAMP)"
                )
            spark.sql(f"""
            MERGE INTO {catalog}.{database}.{table_name} AS target
            USING _new_rows AS source
            ON {_on_pred}
            WHEN NOT MATCHED BY SOURCE AND target.Audit_RowIsCurrent = true THEN
              {_nis_action}
        """)
    else:
        _ch_cond = ""
        if _cfg.get("change_hash_enabled"):
            _ch_cond = " AND NOT (target.ChangeHash <=> source.ChangeHash)"
            if _cfg.get("soft_delete_flag"):
                # A reappearing key is un-deleted even when its hash is unchanged
                _ch_cond = (
                    " AND (NOT (target.ChangeHash <=> source.ChangeHash)"
                    " OR coalesce(target.Audit_IsDeleted, false))"
                )
        elif _cfg.get("soft_delete_flag") and _cfg.get("key_only"):
            # Key-only: nothing to compare, so only a reappearing (deleted) key needs a write
            _ch_cond = " AND coalesce(target.Audit_IsDeleted, false)"
        source_df.createOrReplaceTempView("_source_data")
        spark.sql(f"""
        MERGE INTO {catalog}.{database}.{table_name} AS target
        USING _source_data AS source
        ON {_on_pred}
        WHEN MATCHED{_ch_cond} THEN UPDATE SET
          {_update_set}
        WHEN NOT MATCHED THEN INSERT (
          {_insert_cols}
        ) VALUES (
          {_insert_vals}
        ){_not_in_src}
    """)
except BaseException:
    _release_source_cache()  # failed: do not leave the cache pinned on a shared cluster
    raise

# COMMAND ----------

try:
    # High-watermark commit — written only after target table MERGE succeeds
    # If the MERGE above raised an exception this cell is not reached,
    # ensuring the watermark only advances when processing completed successfully.
    if _cfg.get("use_high_watermark"):
        # Data-derived values (max file path / max HWM) are bound as DataFrame data
        # and MERGE'd via a temp view — never f-string-interpolated into SQL text —
        # so a value containing a quote cannot break the statement or inject SQL.
        from pyspark.sql.types import StructType, StructField, StringType
        _hwm_commit_row = None
        if _cfg.get("hwm_file_path_mode") and _max_file_path:
            _hwm_commit_row = (table_name, "__file_path__", str(_max_file_path))
        elif not _cfg.get("hwm_file_path_mode") and _max_hwm is not None:
            _hwm_commit_row = (table_name, _hwm_col, str(_max_hwm))
        if _hwm_commit_row is not None:
            _hwm_commit_schema = StructType([
                StructField("TableName", StringType(), False),
                StructField("ColumnName", StringType(), False),
                StructField("MaxValue", StringType(), True),
            ])
            _hwm_commit_df = spark.createDataFrame([_hwm_commit_row], schema=_hwm_commit_schema)
            _hwm_commit_view = f"_hwm_commit_src_{table_name}"
            _hwm_commit_df.createOrReplaceTempView(_hwm_commit_view)
            spark.sql(f"""
            MERGE INTO {_hwm_table} AS t
            USING {_hwm_commit_view} AS s
            ON t.TableName = s.TableName AND t.ColumnName = s.ColumnName
            WHEN MATCHED THEN UPDATE SET t.MaxValue = s.MaxValue
            WHEN NOT MATCHED THEN INSERT *
        """)
except BaseException:
    _release_source_cache()  # failed: do not leave the cache pinned on a shared cluster
    raise

# COMMAND ----------

try:
    # Data quality audit write (after MERGE)
    if _cfg.get("expectations_enabled") and _cfg.get("expectations"):
        _exps     = _cfg["expectations"]
        _esafe    = lambda n: "".join(c if (c.isalnum() or c == "_") else "_" for c in n)
        _has_audit = any(_exp.get("action") in ("audit_only", "write_and_audit") for _exp in _exps)
        if _has_audit and "_audit_rows_df" in dir():
            _audit_tbl = f"{catalog}.{database}.{table_name}_Audit_DataQualityViolations"
            try:
                spark.sql(f"""
                DELETE FROM {_audit_tbl}
                WHERE ({" AND ".join(f"ExpKey_{k} IS NOT NULL" for k in _cfg["merge_key_columns"])})
            """)
            except Exception:
                pass
            (_audit_rows_df
                .withColumn("Audit_Timestamp", current_timestamp())
                .withColumn("Audit_TableName", lit(table_name))
                .write.mode("append").saveAsTable(_audit_tbl)
            )
except BaseException:
    _release_source_cache()  # failed: do not leave the cache pinned on a shared cluster
    raise

# COMMAND ----------

try:
    # Infer missing dimension records
    # For each FK column, insert an Unknown placeholder row into the referenced
    # dimension table for any FK value present in source_df but absent from the dimension.
    if _cfg.get("infer_missing_records") and _cfg.get("infer_missing_fk_columns"):
        source_df.createOrReplaceTempView("_infer_src")
        for _fk in _cfg["infer_missing_fk_columns"]:
            _fk_col = _fk["name"]
            _fk_tbl = _fk["foreign_table"]
            # SCD2 dimension: the Unknown row is born current so the SCD2 merge can supersede it
            _fk_cols = ", Audit_RowIsCurrent, Audit_EffectiveDate, Audit_ExpiredDate" if _fk.get("scd2") else ""
            _fk_vals = ", true, CAST('1900-01-01' AS TIMESTAMP), CAST('9999-12-31' AS TIMESTAMP)" if _fk.get("scd2") else ""
            spark.sql(f"""
            INSERT INTO {catalog}.{database}.{_fk_tbl} ({_fk_col}{_fk_cols})
            SELECT DISTINCT s.{_fk_col}{_fk_vals}
            FROM _infer_src s
            LEFT ANTI JOIN {catalog}.{database}.{_fk_tbl} d
            ON s.{_fk_col} = d.{_fk_col}
            WHERE s.{_fk_col} IS NOT NULL
        """)
except BaseException:
    _release_source_cache()  # failed: do not leave the cache pinned on a shared cluster
    raise

# COMMAND ----------

# Release the cached source (the last cell that reads source_df has completed)
_release_source_cache()

# COMMAND ----------

# Table statistics — append-only entry per run
if _cfg.get("table_statistics_enabled"):
    _uc_tbl = f"{catalog}.{database}.{table_name}"
    try:
        _tbl_end = _time.time()
        _duration = round(_tbl_end - _tbl_run_start, 3)
        _rows_after = spark.sql(f"SELECT COUNT(*) AS cnt FROM {_uc_tbl}").collect()[0]["cnt"]
        _hist = spark.sql(f"DESCRIBE HISTORY {_uc_tbl} LIMIT 1").first()
        _metrics = dict(_hist['operationMetrics']) if _hist and _hist['operationMetrics'] else {}
        _ins = int(_metrics.get('numTargetRowsInserted', 0))
        _upd = int(_metrics.get('numTargetRowsUpdated', 0))
        _del = int(_metrics.get('numTargetRowsDeleted', 0))
        # FIX-3: _rows_before is captured before the MERGE/truncate (capture cell);
        # fall back to the MERGE-only derivation only if it was never set.
        if '_rows_before' not in dir():
            _rows_before = _rows_after - _ins + _del
        spark.sql(f"""
            INSERT INTO {catalog}.{database}.Audit_RuntimeTableLog
            (TableName, RunTimestamp, DurationSeconds,
             RowsBefore, RowsAfter, RowsInserted, RowsUpdated, RowsDeleted)
            VALUES
            ('{table_name}', current_timestamp(), {_duration},
             {_rows_before}, {_rows_after}, {_ins}, {_upd}, {_del})
        """)
    except Exception as _stats_err:
        print(f"Warning: table statistics not logged: {_stats_err}")

# COMMAND ----------

# Custom end cell (per-table, from config)
# NOTE: content originates from trusted-internal table configuration.
_end_cell = _cfg.get("end_cell")
if _end_cell:
    exec(compile(_end_cell, "<end_cell>", "exec"), globals())

# COMMAND ----------

# Table maintenance
if _cfg.get("vacuum_enabled") or _cfg.get("optimize_enabled"):
    _uc_tbl = f"{catalog}.{database}.{table_name}"
    if _cfg.get("optimize_enabled"):
        _zcols = _cfg.get("zorder_columns", [])
        if _zcols:
            _zorder_clause = ", ".join(_zcols)
            spark.sql(f"OPTIMIZE {_uc_tbl} ZORDER BY ({_zorder_clause})")
        else:
            spark.sql(f"OPTIMIZE {_uc_tbl}")
    if _cfg.get("vacuum_enabled"):
        _ret = _cfg.get("vacuum_retention_hours", 168)
        spark.sql(f"VACUUM {_uc_tbl} RETAIN {_ret} HOURS")

# COMMAND ----------

# Post-run notebook (runs after all processing)
if _cfg.get("post_run_notebook_path"):
    dbutils.notebook.run(_cfg["post_run_notebook_path"], timeout_seconds=0)

# COMMAND ----------

# Signal successful completion to the orchestrator (RunAllNotebooks).
try:
    _exit_rows = _rows_after
except NameError:
    _exit_rows = "n/a"
dbutils.notebook.exit(f"success: rows_after={_exit_rows}")